CREATE TABLE IF NOT EXISTS public.item_tri_parameters (question_id integer PRIMARY KEY REFERENCES public.questions(id) ON DELETE CASCADE, model text NOT NULL DEFAULT '3PL-estimate', discrimination_a numeric(8,5) NOT NULL DEFAULT 1.0 CHECK (discrimination_a > 0), difficulty_b numeric(8,5) NOT NULL DEFAULT 0, guessing_c numeric(8,5) NOT NULL DEFAULT 0.20 CHECK (guessing_c >= 0 AND guessing_c < 1), calibration_status text NOT NULL DEFAULT 'estimated' CHECK (calibration_status IN ('estimated','calibrated','review')), sample_size integer NOT NULL DEFAULT 0, source text, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.proficiency_assessments (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, title text NOT NULL DEFAULT 'Teste de proficiência inicial', status text NOT NULL DEFAULT 'completed' CHECK (status IN ('draft','in_progress','completed')), started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, question_count integer NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS public.proficiency_results (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, assessment_id bigint NOT NULL REFERENCES public.proficiency_assessments(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, knowledge_area_id integer REFERENCES public.knowledge_areas(id) ON DELETE SET NULL, theta numeric(10,5), estimated_score numeric(8,2), item_count integer NOT NULL DEFAULT 0, accuracy numeric(8,5), model_version text NOT NULL DEFAULT 'tri-estimate-v1', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(assessment_id, knowledge_area_id));
CREATE TABLE IF NOT EXISTS public.study_priorities (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, topic_id integer NOT NULL REFERENCES public.topics(id) ON DELETE CASCADE, priority_score numeric(10,5) NOT NULL DEFAULT 0, priority_level text NOT NULL DEFAULT 'medium' CHECK (priority_level IN ('urgent','high','medium','mastered')), rationale text, completed boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id, topic_id));
CREATE INDEX IF NOT EXISTS idx_item_tri_status ON public.item_tri_parameters(calibration_status); CREATE INDEX IF NOT EXISTS idx_prof_results_user ON public.proficiency_results(user_id, created_at DESC); CREATE INDEX IF NOT EXISTS idx_study_priorities_user ON public.study_priorities(user_id, priority_score DESC);
ALTER TABLE public.item_tri_parameters ENABLE ROW LEVEL SECURITY; ALTER TABLE public.proficiency_assessments ENABLE ROW LEVEL SECURITY; ALTER TABLE public.proficiency_results ENABLE ROW LEVEL SECURITY; ALTER TABLE public.study_priorities ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS item_tri_read_auth ON public.item_tri_parameters; CREATE POLICY item_tri_read_auth ON public.item_tri_parameters FOR SELECT TO authenticated USING (true); DROP POLICY IF EXISTS item_tri_admin_write ON public.item_tri_parameters; CREATE POLICY item_tri_admin_write ON public.item_tri_parameters FOR ALL TO authenticated USING (public.is_admin()) WITH CHECK (public.is_admin());
DROP POLICY IF EXISTS proficiency_assessments_own ON public.proficiency_assessments; CREATE POLICY proficiency_assessments_own ON public.proficiency_assessments FOR ALL TO authenticated USING (user_id = auth.uid() OR public.is_admin()) WITH CHECK (user_id = auth.uid() OR public.is_admin());
DROP POLICY IF EXISTS proficiency_results_own ON public.proficiency_results; CREATE POLICY proficiency_results_own ON public.proficiency_results FOR SELECT TO authenticated USING (user_id = auth.uid() OR public.is_admin());
DROP POLICY IF EXISTS study_priorities_own ON public.study_priorities; CREATE POLICY study_priorities_own ON public.study_priorities FOR ALL TO authenticated USING (user_id = auth.uid() OR public.is_admin()) WITH CHECK (user_id = auth.uid() OR public.is_admin());
